// MinimockUpdateEnumValueInspect logs each unmet expectation
func (m *EnumServiceMock) MinimockUpdateEnumValueInspect() {
	for _, e := range m.UpdateEnumValueMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to EnumServiceMock.UpdateEnumValue at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterUpdateEnumValueCounter := mm_atomic.LoadUint64(&m.afterUpdateEnumValueCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.UpdateEnumValueMock.defaultExpectation != nil && afterUpdateEnumValueCounter < 1 {
		if m.UpdateEnumValueMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to EnumServiceMock.UpdateEnumValue at\n%s", m.UpdateEnumValueMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to EnumServiceMock.UpdateEnumValue at\n%s with params: %#v", m.UpdateEnumValueMock.defaultExpectation.expectationOrigins.origin, *m.UpdateEnumValueMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcUpdateEnumValue != nil && afterUpdateEnumValueCounter < 1 {
		m.t.Errorf("Expected call to EnumServiceMock.UpdateEnumValue at\n%s", m.funcUpdateEnumValueOrigin)
	}

	if !m.UpdateEnumValueMock.invocationsDone() && afterUpdateEnumValueCounter > 0 {
		m.t.Errorf("Expected %d calls to EnumServiceMock.UpdateEnumValue at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.UpdateEnumValueMock.expectedInvocations), m.UpdateEnumValueMock.expectedInvocationsOrigin, afterUpdateEnumValueCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *EnumServiceMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockCreateEnumInspect()

			m.MinimockCreateEnumValueInspect()

			m.MinimockDeleteEnumInspect()

			m.MinimockDeleteEnumValueInspect()

			m.MinimockGetEnumInspect()

			m.MinimockGetEnumValueInspect()

			m.MinimockUpdateEnumInspect()

			m.MinimockUpdateEnumValueInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *EnumServiceMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *EnumServiceMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockCreateEnumDone() &&
		m.MinimockCreateEnumValueDone() &&
		m.MinimockDeleteEnumDone() &&
		m.MinimockDeleteEnumValueDone() &&
		m.MinimockGetEnumDone() &&
		m.MinimockGetEnumValueDone() &&
		m.MinimockUpdateEnumDone() &&
		m.MinimockUpdateEnumValueDone()
}
